def f(text: str) -> str:
    """Converts each character to its hexadecimal ASCII value, appending '_alt' to the last character if it is a letter."""
    if not text:
        return ''
    result = []
    for i, c in enumerate(text):
        hex_val = f'{ord(c):02x}'
        if i == len(text) - 1 and c.isalpha():
            hex_val += '_alt'
        result.append(hex_val)
    return ' '.join(result)
